int process_auth_ticket(struct ceph_auth_client *ac, struct ceph_crypto_key *secret, void **p, void *end) {
    int ret = -EINVAL;
    struct ceph_auth_ticket *ticket;
    struct ceph_auth_ticket_handler *handler;

    if (!ac || !secret || !p || !end || *p >= end) {
        return -EINVAL;
    }

    // Decode ticket type and version
    le32_decoded type, version;
    if ((char*)(p) + sizeof(type) + sizeof(version) > (char*)end) {
        return -EINVAL;
    }
    type = ceph_decode_32(p);
    version = ceph_decode_32(p);

    handler = ceph_get_auth_ticket_handler(ac, type);
    if (!handler) {
        return -ENOTSUPP;
    }

    // Allocate ticket structure
    ticket = kmalloc(sizeof(*ticket), GFP_NOFS);
    if (!ticket) {
        return -ENOMEM;
    }

    // Decrypt ticket data
    if (secret->data && secret->data_len > 0) {
        ret = ceph_decrypt_ticket(secret, p, end, ticket);
        if (ret < 0) {
            kfree(ticket);
            return ret;
        }
    }

    // Extract new session key and validity period
    le64_decoded valid_from, valid_until;
    struct ceph_crypto_key *new_key;

    valid_from = ceph_decode_64(p);
    valid_until = ceph_decode_64(p);
    new_key = ceph_extract_crypto_key(p, end);
    if (IS_ERR(new_key)) {
        ret = PTR_ERR(new_key);
        kfree(ticket);
        return ret;
    }

    ticket->valid_from = cpu_to_le64(valid_from);
    ticket->valid_until = cpu_to_le64(valid_until);
    ticket->key = new_key;

    // Update handler session key and ticket info
    ret = handler->update(ac, ticket);
    if (ret < 0) {
        ceph_free_crypto_key(new_key);
        kfree(ticket);
        return ret;
    }

    return 0;
}

int ceph_auth_client_process_ticket(struct ceph_auth_client *ac,
                                    struct ceph_crypto_key *secret,
                                    void **p, void *end)
{
    int ret = -EINVAL;
    struct ceph_auth_ticket_handler *handler = NULL;
    struct ceph_auth_ticket *ticket = NULL;
    struct ceph_crypto_key new_key;
    void *decrypted_data = NULL;
    u64 ticket_type, version;

    if (!ac || !secret || !p || !*p || *p >= end)
        goto out;

    if (end - *p < sizeof(ticket_type) + sizeof(version))
        goto out;

    ticket_type = ceph_decode_64(p);
    version = ceph_decode_64(p);

    handler = ceph_auth_get_ticket_handler(ac, ticket_type);
    if (!handler)
        goto out;

    ticket = ceph_auth_ticket_new(handler, ticket_type, version);
    if (!ticket)
        goto out;

    ret = ceph_auth_ticket_decode(ticket, p, end);
    if (ret < 0)
        goto out;

    if (secret->len) {
        decrypted_data = ceph_auth_ticket_decrypt(ticket, secret);
        if (!decrypted_data) {
            ret = -ENOMEM;
            goto out;
        }
        ret = ceph_auth_ticket_extract_key(ticket, decrypted_data, &new_key);
    } else {
        ret = ceph_auth_ticket_extract_key(ticket, NULL, &new_key);
    }

    if (ret < 0)
        goto out;

    ret = ceph_auth_client_set_key(ac, &new_key);
    if (ret < 0)
        goto out;

    ret = ceph_auth_ticket_update_handler(ticket, handler);
    if (ret < 0)
        goto out;

    ret = 0;

out:
    ceph_auth_ticket_free(ticket);
    ceph_crypto_key_free(&new_key);
    kfree(decrypted_data);
    return ret;
}

int process_ticket(struct ceph_auth_client *ac, struct ceph_crypto_key *secret,
                   void **p, void *end) {
  int ret = -EINVAL;
  struct ceph_auth_ticket_handler *handler = NULL;
  void *ticket_data = NULL;
  struct ceph_crypto_key new_key;
  struct ceph_ticket_info info;
  u32 ticket_type, version;

  // Decode ticket type and version
  if (*p + sizeof(u32) * 2 > end) {
    goto out;
  }

  ticket_type = ceph_decode_32(p);
  version = ceph_decode_32(p);

  // Retrieve the appropriate ticket handler
  handler = ceph_get_ticket_handler(ac, ticket_type);
  if (!handler) {
    goto out;
  }

  // Decrypt the ticket data using the secret key
  if (secret && secret->data_len > 0) {
    ticket_data = ceph_decrypt_ticket(secret, *p, end - *p);
    if (!ticket_data) {
      goto out;
    }
    *p = ticket_data;
  }

  // Extract the new session key and validity period
  if (*p + sizeof(struct ceph_crypto_key) > end) {
    goto out;
  }

  ret = ceph_decode_crypto_key(*p, &new_key);
  if (ret < 0) {
    goto out;
  }

  *p += sizeof(struct ceph_crypto_key);

  if (*p + sizeof(u64) * 2 > end) {
    goto out;
  }

  info.start = ceph_decode_64(p);
  info.expiry = ceph_decode_64(p);

  // Extract the ticket blob
  if (*p + sizeof(u32) > end) {
    goto out;
  }

  info.blob_len = ceph_decode_32(p);
  if (*p + info.blob_len > end) {
    goto out;
  }

  info.blob = *p;
  *p += info.blob_len;

  // Update the session key and ticket information in the handler
  ret = ceph_set_ticket_info(handler, &new_key, &info);
  if (ret < 0) {
    goto out;
  }

  ret = 0;

out:
  if (ticket_data) {
    free(ticket_data);
  }

  if (ret < 0) {
    ceph_auth_ticket_handler_put(handler);
  }

  return ret;
}

int ceph_auth_client_process_ticket(struct ceph_auth_client *ac,
                                    struct ceph_crypto_key *secret,
                                    void **p, void *end) {
    int ret = -EINVAL;
    uint8_t type;
    uint8_t version;
    struct ceph_auth_ticket_handler *handler = NULL;
    struct ceph_auth_ticket ticket;
    void *decrypted = NULL;
    size_t decrypted_len = 0;

    if (!ac || !secret || !p || !*p || !end || *p > end) {
        return -EINVAL;
    }

    type = ceph_decode_8(p, end);
    version = ceph_decode_8(p, end);

    handler = ceph_get_auth_ticket_handler(type);
    if (!handler) {
        goto out;
    }

    if (version != handler->version) {
        ret = -ENOTSUPP;
        goto out;
    }

    ticket.encrypted = ceph_decode_8(p, end);
    ticket.key_len = ceph_decode_32(p, end);
    ticket.blob_len = ceph_decode_32(p, end);

    if (ticket.key_len > 0) {
        ticket.key = ceph_decode_data(p, end, ticket.key_len);
        if (!ticket.key || *p > end) {
            ret = -EINVAL;
            goto out;
        }
    }

    if (ticket.blob_len > 0) {
        ticket.blob = ceph_decode_data(p, end, ticket.blob_len);
        if (!ticket.blob || *p > end) {
            ret = -EINVAL;
            goto out;
        }
    }

    if (ticket.encrypted) {
        ret = ceph_decrypt_ticket(&decrypted, &decrypted_len, secret, &ticket);
        if (ret < 0) {
            goto out;
        }

        ret = ceph_auth_ticket_process(handler, &ticket, decrypted, decrypted_len);
    } else {
        ret = ceph_auth_ticket_process(handler, &ticket, NULL, 0);
    }

    if (ret >= 0) {
        ac->current_handler = handler;
        ac->session_key = ticket.key;
        ac->session_key_len = ticket.key_len;
        ac->ticket_blob = ticket.blob;
        ac->ticket_blob_len = ticket.blob_len;
    }

out:
    if (decrypted) {
        free(decrypted);
    }

    if (ret < 0) {
        ceph_auth_ticket_cleanup(&ticket);
    }

    return ret;
}

int ceph_auth_client_process_ticket(struct ceph_auth_client *ac,
                                    struct ceph_crypto_key *secret,
                                    void **p, void *end) {
    int ret = -EINVAL;
    struct ceph_auth_ticket_handler *handler;
    void *ticket_data;
    size_t ticket_len;
    struct ceph_crypto_key *new_key = NULL;
    struct ceph_timespec since;

    // Decode ticket type and version
    if ((ret = ceph_decode_auth_ticket(ac, p, end, &handler, &ticket_data,
                                       &ticket_len, &since)) < 0) {
        goto out;
    }

    // Retrieve ticket handler
    if (!handler) {
        ret = -ENOTSUP;
        goto out;
    }

    // Decrypt ticket data if needed
    if (handler->encrypt) {
        ret = ceph_auth_decrypt(ticket_data, ticket_len, secret, &new_key);
        if (ret < 0)
            goto out;
    }

    // Extract session key, validity period, and ticket blob
    ret = handler->decode_ticket(ac, new_key, &since, p, end);
    if (ret < 0)
        goto out;

    // Update session key and ticket info in the handler
    ret = handler->update(ac, new_key, &since);
    if (ret < 0)
        goto out;

    ret = 0;

out:
    ceph_put_crypto_key(new_key);
    return ret;
}
